INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'Mathematics', 'Unit 7', 'Molarum Grade 10 — Mathematics Unit 7: Coordinate Geometry', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 7: Coordinate Geometry.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('e18a660b-df91-41da-8fc3-8db4e7cf5934'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'Which of the following is the distance formula for the segment joining P(x1, y1) and Q(x2, y2)?', 'd = √((x2 − x1)^2 + (y2 − y1)^2)', 'The excerpt defines the distance between P(x1,y1) and Q(x2,y2) as d = √((x2 − x1)^2 + (y2 − y1)^2) using Pythagoras in ΔPQR.', 0),('01af34a7-1d01-43f1-897a-751fec56d9c3'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the midpoint formula for the endpoints P(x1, y1) and Q(x2, y2)?', '((x1 + x2)/2, (y1 + y2)/2)', 'The excerpt gives the midpoint R as ((x1 + x2)/2, (y1 + y2)/2) by averaging coordinates of the endpoints.', 1),('384f9f91-1f2f-47a9-8105-6013724b9f62'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'Which expression gives the gradient m of the line through P(x1, y1) and Q(x2, y2) with x1 ≠ x2?', 'm = (y2 − y1)/(x2 − x1)', 'Definition 7.2 in the excerpt defines slope as m = (y2 − y1)/(x2 − x1) for x1 ≠ x2.', 2),('a84e3268-2b37-49de-88c1-d7d346dc6846'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the standard equation of a circle with centre (h, k) and radius r?', '(x − h)^2 + (y − k)^2 = r^2', 'The excerpt states the standard form of a circle as (x − h)^2 + (y − k)^2 = r^2 for centre (h,k) and radius r.', 3),('3432791a-06d0-46f7-8e96-811e1cd0f84a'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the distance between A(2,1) and B(8,9) as found in the example?', '10', 'The example computes d = √((8−2)^2 + (9−1)^2) = √(36+64) = √100 = 10, so the distance is 10 units.', 4),('e00a9fda-6c28-4627-8734-a513d532abd8'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'From the example, what is the distance between P(9,13) and Q(4,1)?', '13', 'The example calculates d = √((4−9)^2 + (1−13)^2) = √(25+144) = √169 = 13 units.', 5),('489bcaec-be09-4e39-83b5-bdd6e076a546'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'In the example, what is the distance between R(0, −1) and S(−3, 3)?', '5', 'The example uses d = √((−3−0)^2 + (3−(−1))^2) = √(9+16) = √25 = 5 units, so the distance is 5.', 6),('56558c25-d4fa-46be-8168-4e487402ae19'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the distance between A(1,2) and B(4,2) from the example dealing with horizontal intervals?', '3', 'Because AB is horizontal, distance d = |x2 − x1| = |4 − 1| = 3 as shown in the example for horizontal intervals.', 7),('5756afd3-c4bb-4e24-86c6-122764e3a025'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'Find the gradient of the line passing through P(2,1) and Q(4,7) as in the examples.', '3', 'Using m = (y2 − y1)/(x2 − x1) gives m = (7 − 1)/(4 − 2) = 6/2 = 3, as in the worked example.', 8),('20c72f60-9f9a-4cb5-84db-ed9d6f919db7'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the slope of the line through P(5, −1) and Q(6, 9) from the examples?', '10', 'From the example m = (9 − (−1))/(6 − 5) = 10/1 = 10, so the slope is 10.', 9),('09f787ea-4e9b-40ba-8442-ade6361c6f2e'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'Compute the slope of the line joining P(8,3) and Q(3,13) as in the examples.', '−2', 'Using m = (13 − 3)/(3 − 8) = 10/(−5) = −2, matching the example showing this calculation.', 10),('fd042b74-9145-41a7-8c98-2cce65fd871c'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the slope of the line through P(7,3) and Q(−4,3) according to the example?', '0', 'The example notes this line is horizontal so m = (3 − 3)/(−4 − 7) = 0, hence slope zero.', 11),('1b7a41e5-3799-4259-8dd2-cffbf3ba8512'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'According to the text, what is true for a line whose slope m > 0?', 'The line rises from left to right', 'The excerpt explains that if m > 0 then the line rises from left to right, describing the sign of slope relation to steepness.', 12),('0b8d0389-1b71-4b16-82c4-842f56e5a306'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the slope of a line whose angle of inclination is 45° according to the examples?', '1', 'The example shows m = tanθ and for θ = 45°, tan45° = 1, so the slope is 1.', 13),('5a26c08a-5ef8-4e14-8322-98913278e196'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the slope of a line with angle of inclination 120° as given in the example?', '−√3', 'The example explains for 120° the slope is −tan60° = −√3, so the correct value is −√3.', 14),('b799328b-4443-4800-88d6-b769546a29eb'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'Which is the two-point form of the equation of a line through (x1,y1) and (x2,y2)?', 'y − y1 = ((y2 − y1)/(x2 − x1))(x − x1)', 'The two-point form given in the excerpt is y − y1 = ((y2 − y1)/(x2 − x1))(x − x1), derived from equal slopes for collinear points.', 15),('5d9e0d92-cc4a-482d-8b05-31c2c04877c2'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the point-slope form of the equation of a line through (x1, y1) with slope m?', 'y − y1 = m(x − x1)', 'The excerpt lists the point-slope form as y − y1 = m(x − x1) for a line with slope m through (x1,y1).', 16),('ab11952f-78ff-4693-8f06-78d13b84e1dd'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'If a line has equation y = 2x + 1, what is the slope of any line perpendicular to it (as used in an example)?', '−1/2', 'The excerpt shows perpendicular slopes satisfy m1·m2 = −1; with m1 = 2, the perpendicular slope is m2 = −1/2.', 17),('080bd3ea-59db-4bee-81ec-87b04f03c3bd'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'According to Theorem 7.1 in the excerpt, if two non-vertical lines l1 and l2 are parallel then:', 'They have the same slope', 'Theorem 7.1 states parallel non-vertical lines have equal slopes (m1 = m2), as shown by equal angles of inclination.', 18),('8f7a7264-1828-45e7-81fc-96207c296f5c'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'multiple_choice', 'What is the condition for two non-vertical lines with slopes m1 and m2 to be perpendicular as stated in Theorem 7.2?', 'm1 · m2 = −1', 'Theorem 7.2 in the excerpt gives the perpendicular condition m1·m2 = −1 for two non-vertical lines.', 19),('8333257a-67e6-4598-8564-03efedfe8d12'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'true_false', 'The distance from point A to point B is the same as the distance from B to A.', 'True', 'The excerpt explicitly states distance from A to B equals distance from B to A, because distance is symmetric.', 20),('2ecc7983-12c7-4b7d-820f-369431c1e85b'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'true_false', 'A vertical line has slope zero.', 'False', 'The excerpt states a vertical line has no slope, while a horizontal line has slope zero, so the statement is false.', 21),('cb5708ca-d5a5-4503-86f7-e7b0a981f4a9'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'true_false', 'A horizontal line has slope 0.', 'True', 'The excerpt notes that a horizontal line is parallel to the x-axis and therefore has slope m = 0.', 22),('67ae9795-f489-42a1-8757-4dded3a0672b'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'true_false', 'The equation x^2 + y^2 = a^2 represents a circle centered at the origin with radius a.', 'True', 'The excerpt derives x^2 + y^2 = a^2 as the equation of a circle centered at the origin with radius a by distance from (0,0).', 23),('2378ccf0-891f-4850-864d-bfd38e41663c'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Write the distance formula between P(x1, y1) and Q(x2, y2).', 'd = √((x2 − x1)^2 + (y2 − y1)^2)', 'Definition 7.1 gives the distance as d = √((x2 − x1)^2 + (y2 − y1)^2) derived from Pythagoras in right triangle PQR.', 24),('da9f88c4-0519-431f-8579-cf6ac5438798'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'State the midpoint formula for the segment joining P(x1, y1) and Q(x2, y2).', '((x1 + x2)/2, (y1 + y2)/2)', 'The excerpt gives the midpoint R as R((x1 + x2)/2, (y1 + y2)/2) by averaging the coordinates of the endpoints.', 25),('b9dc502e-ddd7-4e66-883e-d0ef52a5746c'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Give the formula for the slope m of the line through points (x1,y1) and (x2,y2).', 'm = (y2 − y1)/(x2 − x1)', 'The excerpt defines slope m as the ratio of change in y to change in x, m = (y2 − y1)/(x2 − x1) for x1 ≠ x2.', 26),('259c4888-c318-4c55-86fd-c7d6868636b5'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Write the standard equation of a circle with centre (h,k) and radius r.', '(x − h)^2 + (y − k)^2 = r^2', 'The excerpt states the standard equation of a circle is (x − h)^2 + (y − k)^2 = r^2 for center (h,k) and radius r.', 27),('fea00fb2-a5e9-4057-8688-f3ad29b3a2a4'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'State the point-slope form of the equation of a line.', 'y − y1 = m(x − x1)', 'The excerpt gives point-slope form as y − y1 = m(x − x1) for a line with slope m through (x1,y1).', 28),('4e8d9597-1476-4e06-8797-f98d6e3113cc'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Write the two-point form of the equation of a line through (x1,y1) and (x2,y2).', 'y − y1 = ((y2 − y1)/(x2 − x1))(x − x1)', 'The excerpt derives the two-point form as y − y1 = ((y2 − y1)/(x2 − x1))(x − x1) from equal slopes for three collinear points.', 29),('00576e03-d365-44df-852a-20982618e3e2'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'State the section formula for the point R dividing PQ internally in the ratio p:q.', 'R( (p x2 + q x1)/(p + q) , (p y2 + q y1)/(p + q) )', 'The excerpt presents the section formula R(x0,y0) = ( (p x2 + q x1)/(p+q) , (p y2 + q y1)/(p+q) ) for internal division in ratio p:q.', 30),('952b4a11-24e7-4685-89d0-679ed451d1c9'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'State the condition on slopes m1 and m2 for two non-vertical lines to be perpendicular.', 'm1 · m2 = −1', 'Theorem 7.2 in the excerpt states two non-vertical lines are perpendicular iff their slopes satisfy m1·m2 = −1.', 31),('1b0d0ecb-435a-43d3-8a9f-14f30674cf31'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between A(2, 5) and B(4, 7) (Exercise 7.2 a).', '2√2', 'Compute d = √((4−2)^2 + (7−5)^2) = √(4 + 4) = √8 = 2√2, using the distance formula from the excerpt.', 32),('76121d3d-7e72-41a5-8b1a-d63c3ac3ac64'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between M(−3, −2) and N(2, −2) (Exercise 7.1 b).', '5', 'The segment is horizontal so d = |x2 − x1| = |2 − (−3)| = 5, as given by the horizontal case in the excerpt.', 33),('cdc7de5c-be0a-4226-8fc7-e4138a1e02b0'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Calculate the distance between P(4,1) and Q(4, −2) (Exercise 7.1 c).', '3', 'Since the points have same x-coordinate the segment is vertical and d = |y2 − y1| = |−2 − 1| = 3, following the vertical-case formula in the excerpt.', 34),('ae489a02-dd5c-4229-845b-bef2465e831f'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between P(−3,5) and Q(4,10) (Exercise 7.2 b).', '√74', 'Use d = √((4−(−3))^2 + (10−5)^2) = √(7^2 + 5^2) = √(49+25) = √74, as per the distance formula.', 35),('d3e176d7-0155-42eb-89b2-2afccf32fb55'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between R(9,5) and S(6, −3) (Exercise 7.2 c).', '√73', 'Compute d = √((6−9)^2 + (−3−5)^2) = √((−3)^2 + (−8)^2) = √(9+64) = √73, using the excerpt''s distance formula.', 36),('ec634786-752b-4e1e-8d1e-4fe4deb72abe'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between M(−4, −3) and N(5, 7) (Exercise 7.2 d).', '√181', 'Use d = √((5−(−4))^2 + (7−(−3))^2) = √(9^2 + 10^2) = √(81+100) = √181, via the distance formula in the text.', 37),('8bc4681c-8211-4816-8a69-d005874c26fa'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between T(−5, −2) and S(0, −14) (Exercise 7.2 e).', '13', 'Compute d = √((0−(−5))^2 + (−14−(−2))^2) = √(5^2 + (−12)^2) = √(25+144) = √169 = 13, following the excerpt.', 38),('9bd52cbd-95c9-4809-8f38-dd591e99e02d'::uuid, '3a1cc266-46d5-4c19-8106-436a23d3119e'::uuid, 'fill_blank', 'Find the distance between the origin and P(√2, √2) (Exercise 7.2 f).', '2', 'Using d = √(x^2 + y^2) for the origin yields d = √((√2)^2 + (√2)^2) = √(2+2) = √4 = 2, as shown in the exercise.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
